 protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);mouseX=e.X;mouseY=e.Y;string old=hoverNav;hoverNav="";for(int i=0;i<NavY.Length;i++)if(new Rectangle(10,NavY[i],174,40).Contains(e.Location))hoverNav=NavKeys[i];if(new Rectangle(10,507,174,40).Contains(e.Location))hoverNav="account";if(new Rectangle(10,553,174,40).Contains(e.Location))hoverNav="Configurações";int hc=-1;if(IsActionPage)for(int i=0;i<6;i++){int col=i%2,row=i/2;if(new Rectangle(222+col*326,213+row*137,314,125).Contains(e.Location))hc=i;}if(old!=hoverNav||hc!=hoverCard||hc>=0){hoverCard=hc;Invalidate();}Cursor=hoverNav!=""||hoverCard>=0?Cursors.Hand:Cursors.Default;}
 protected override void OnMouseLeave(EventArgs e){hoverNav="";hoverCard=-1;Invalidate();base.OnMouseLeave(e);}
 protected override void OnMouseClick(MouseEventArgs e){base.OnMouseClick(e);IceAudio.Click();if(new Rectangle(1026,5,43,34).Contains(e.Location)){var form=FindForm();if(form!=null)form.BeginInvoke(new Action(()=>form.WindowState=FormWindowState.Minimized));return;}if(new Rectangle(1113,5,50,34).Contains(e.Location)){FindForm().Close();return;}for(int i=0;i<NavY.Length;i++)if(new Rectangle(10,NavY[i],174,40).Contains(e.Location)){navigate(NavKeys[i]);return;}if(new Rectangle(10,507,174,40).Contains(e.Location)){navigate("account");return;}if(new Rectangle(10,553,174,40).Contains(e.Location)){navigate("Configurações");return;}if(page=="Início"){string[] targets={"Windows","Jogos","Hardware","Reparos","Aplicativos","Recuperação"};for(int i=0;i<6;i++){int col=i%3,row=i/3;if(new Rectangle(212+col*222,265+row*180,210,166).Contains(e.Location)){navigate(targets[i]);return;}}if(new Rectangle(908,574,210,42).Contains(e.Location)){navigate("Windows");return;}return;}if(page=="Minha conta"){if(new Rectangle(482,502,238,45).Contains(e.Location)){navigate("logout");return;}if(new Rectangle(232,502,238,45).Contains(e.Location)||new Rectangle(783,551,333,44).Contains(e.Location)){try{Process.Start(new ProcessStartInfo("https://iceotimizacoes.store/#planos"){UseShellExecute=true});}catch{}return;}return;}if(page=="Configurações"){Rectangle[] boxes={new Rectangle(222,158,444,92),new Rectangle(680,158,456,92),new Rectangle(222,264,444,92),new Rectangle(680,264,456,92),new Rectangle(222,370,444,92),new Rectangle(680,370,456,92)};for(int i=0;i<boxes.Length;i++)if(boxes[i].Contains(e.Location)){settings[i]=!settings[i];if(i==0)IceAudio.Enabled=settings[i];if(i==1)IceEffects.AnimationsEnabled=settings[i];Invalidate();return;}if(new Rectangle(902,534,210,45).Contains(e.Location)){try{Process.Start(new ProcessStartInfo("https://iceotimizacoes.store/"){UseShellExecute=true});}catch{}return;}return;}if(page=="Hardware")return;
  if(new Rectangle(222,163,144,36).Contains(e.Location)){foreach(var a in Filtered().Skip(offset).Take(6))selected.Add(a.id);Invalidate();return;}if(new Rectangle(374,163,139,36).Contains(e.Location)){selected.Clear();onlySelected=false;offset=0;Invalidate();return;}if(new Rectangle(521,163,130,36).Contains(e.Location)){onlySelected=!onlySelected;offset=0;Invalidate();return;}if(new Rectangle(889,641,247,45).Contains(e.Location)&&selected.Count>0){execute(items.Where(a=>selected.Contains(a.id)).ToArray());return;}
  var filtered=Filtered();for(int i=0;i<6&&offset+i<filtered.Count;i++){int col=i%2,row=i/2;if(new Rectangle(222+col*326,213+row*137,314,125).Contains(e.Location)){var a=filtered[offset+i];if(!selected.Add(a.id))selected.Remove(a.id);Invalidate();return;}}
 }
 void Button(Graphics g,Rectangle r,string label,bool active){Round(g,r,9,active?Color.FromArgb(10,70,102):Color.FromArgb(6,26,44),active?Color.FromArgb(58,202,242):Line);DrawText(g,label,r,8.5f,active,active?White:Muted,ContentAlignment.MiddleCenter);}
 void DrawDiamond(Graphics g,Rectangle r){Point[] a={new Point(r.X+r.Width/2,r.Y),new Point(r.Right,r.Y+r.Height/2),new Point(r.X+r.Width/2,r.Bottom),new Point(r.X,r.Y+r.Height/2)};using(var b=new LinearGradientBrush(r,Color.White,Color.FromArgb(21,171,245),LinearGradientMode.ForwardDiagonal))g.FillPolygon(b,a);using(var p=new Pen(Color.FromArgb(137,235,255)))g.DrawPolygon(p,a);}
 static void Round(Graphics g,Rectangle r,int radius,Color fill,Color stroke,int width=1){using(var path=Path(r,radius)){using(var b=new SolidBrush(fill))g.FillPath(b,path);if(stroke.A>0)using(var p=new Pen(stroke,width))g.DrawPath(p,path);}}
 static void Round(Graphics g,Rectangle r,int radius,Brush fill,Color stroke,int width=1){using(var path=Path(r,radius)){g.FillPath(fill,path);if(stroke.A>0)using(var p=new Pen(stroke,width))g.DrawPath(p,path);}}
 static GraphicsPath Path(Rectangle r,int d){var p=new GraphicsPath();p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
 static void DrawText(Graphics g,string value,Rectangle r,float size,bool bold,Color color,ContentAlignment align=ContentAlignment.MiddleLeft){using(var f=new Font("Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular)){var flags=TextFormatFlags.EndEllipsis|TextFormatFlags.NoPadding;if(align==ContentAlignment.MiddleCenter)flags|=TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter;else flags|=TextFormatFlags.Left|TextFormatFlags.VerticalCenter;TextRenderer.DrawText(g,value,f,r,color,flags);}}
 static void DrawParagraph(Graphics g,string value,Rectangle r,float size,Color color){using(var f=new Font("Segoe UI",size)){TextRenderer.DrawText(g,value,f,r,color,TextFormatFlags.Left|TextFormatFlags.Top|TextFormatFlags.WordBreak|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPadding);}}
}

static class IceAudio {
 public static bool Enabled=true;static SoundPlayer player;
 public static void Click(){if(!Enabled)return;try{if(player==null){var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("ice-click.wav");if(stream==null)return;player=new SoundPlayer(stream);player.Load();}player.Play();}catch{}}
}

static class IceEffects {
 public static bool AnimationsEnabled=true;
 public static void DrawSnow(Graphics g,int width,int height){if(!AnimationsEnabled)return;long t=Environment.TickCount&0x7fffffff;for(int i=0;i<26;i++){float speed=.018f+(i%5)*.005f;float x=(float)((i*173+(t*speed*(1+(i%3)*.12)))%Math.Max(1,width));float y=(float)((i*89+(t*(.025f+(i%4)*.007f)))%Math.Max(1,height));int size=1+i%3;using(var b=new SolidBrush(Color.FromArgb(35+(i%4)*15,190,235,255)))g.FillEllipse(b,x,y,size,size);}}
}

