  string log=SaveLog(results);var saved=LabelOf("Registro salvo em: "+log,new Rectangle(38,536,535,25),7.5f,false,muted);Controls.Add(saved);var done=new Button{Text="Concluir",FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(12,112,171),ForeColor=white,Font=new Font("Segoe UI",9,FontStyle.Bold),Cursor=Cursors.Hand};done.FlatAppearance.BorderColor=cyan;done.SetBounds(594,542,132,42);done.Click+=(s,e)=>Close();Controls.Add(done);
 }
 Label LabelOf(string text,Rectangle bounds,float size,bool bold,Color color){return new Label{Text=text,Bounds=bounds,Font=new Font("Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular),ForeColor=color,BackColor=Color.Transparent,TextAlign=ContentAlignment.MiddleLeft,AutoEllipsis=true};}
 string SaveLog(IList<BatchResult> results){try{string folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ice optimizer","logs");Directory.CreateDirectory(folder);string file=Path.Combine(folder,DateTime.Now.ToString("yyyy-MM-dd_HH-mm-ss")+".txt");var lines=new List<string>{"ICE OPTIMIZER — RELATÓRIO DE EXECUÇÃO","Data: "+DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss"),new string('=',64)};foreach(var result in results)lines.Add((result.code==0?"[SUCESSO] ":"[ERRO] ")+result.title+" — "+result.status);File.WriteAllLines(file,lines);return file;}catch{return "não foi possível salvar o arquivo";}}
}

